'use client'
import { cn, useSignalEffect, useSignals } from '@cascivo/core'
import { useRef } from 'react'
import type { CSSProperties, HTMLAttributes, ReactNode } from 'react'
import styles from './scroll-area.module.css'

/** Whether the browser can answer `scrollable: top/bottom` in CSS. SSR-safe. */
function supportsScrollState(): boolean {
  return (
    typeof CSS !== 'undefined' &&
    typeof CSS.supports === 'function' &&
    CSS.supports('container-type', 'scroll-state')
  )
}

export interface ScrollAreaProps extends HTMLAttributes<HTMLDivElement> {
  /** Max block size of the scroll container (any CSS length). */
  height?: string
  /** Max inline size of the scroll container (any CSS length). */
  width?: string
  /**
   * Which axes may scroll
   *
   * @defaultValue `vertical`
   * @see the component manifest
   */
  orientation?: 'vertical' | 'horizontal' | 'both'
  /**
   * Edge affordance: box-shadow, a mask-image fade, or none
   *
   * @defaultValue `shadow`
   * @see the component manifest
   */
  edges?: 'shadow' | 'mask' | 'none'
  children?: ReactNode
}

export function ScrollArea({
  height,
  width,
  orientation = 'vertical',
  edges = 'shadow',
  className,
  style,
  children,
  ...props
}: ScrollAreaProps) {
  useSignals()
  const nodeRef = useRef<HTMLDivElement | null>(null)

  // Drive scroll-shadow data attributes from the scroll position. No useEffect —
  // useSignalEffect runs the subscription once on mount and cleans up on unmount.
  //
  // Skipped entirely where `scroll-state` container queries can answer the same question in
  // CSS (see the @supports block in the stylesheet): a supporting browser ships no scroll
  // listener at all rather than running one whose output nothing reads. `edges="mask"` still
  // needs it — a mask paints on the scroller itself, which a container query cannot reach.
  useSignalEffect(() => {
    if (edges === 'shadow' && supportsScrollState()) return
    const node = nodeRef.current
    if (!node) return

    const update = (): void => {
      const atTop = node.scrollTop <= 0
      const atBottom = node.scrollTop + node.clientHeight >= node.scrollHeight - 1
      const atStart = node.scrollLeft <= 0
      const atEnd = node.scrollLeft + node.clientWidth >= node.scrollWidth - 1
      node.toggleAttribute('data-scroll-top', !atTop)
      node.toggleAttribute('data-scroll-bottom', !atBottom)
      node.toggleAttribute('data-scroll-start', !atStart)
      node.toggleAttribute('data-scroll-end', !atEnd)
    }

    update()
    node.addEventListener('scroll', update, { passive: true })
    return () => {
      node.removeEventListener('scroll', update)
    }
  })

  const sizeStyle = {
    ...(height !== undefined ? { '--cascivo-scroll-area-height': height } : {}),
    ...(width !== undefined ? { '--cascivo-scroll-area-width': width } : {}),
    ...style,
  } as CSSProperties

  return (
    <div
      ref={nodeRef}
      data-orientation={orientation}
      data-edges={edges}
      className={cn(styles['root'], className)}
      style={sizeStyle}
      {...props}
    >
      {children}
    </div>
  )
}

@layer cascivo.component {
  .root {
    max-block-size: var(--cascivo-scroll-area-height, none);
    max-inline-size: var(--cascivo-scroll-area-width, none);
    scrollbar-width: thin;
    scrollbar-color: var(--cascivo-color-border) transparent;

    &[data-orientation='vertical'] {
      overflow-x: hidden;
      overflow-y: auto;
    }

    &[data-orientation='horizontal'] {
      overflow-x: auto;
      overflow-y: hidden;
    }

    &[data-orientation='both'] {
      overflow: auto;
    }

    &::-webkit-scrollbar {
      inline-size: 0.5rem;
      block-size: 0.5rem;
    }

    &::-webkit-scrollbar-track {
      background: transparent;
    }

    &::-webkit-scrollbar-thumb {
      background-color: var(--cascivo-color-border);
      border-radius: var(--cascivo-radius-control);
    }

    &::-webkit-scrollbar-thumb:hover {
      background-color: var(--cascivo-color-text-subtle);
    }

    /* Scroll shadows — gradients appear only when content overflows in that direction. */
    background:
      linear-gradient(var(--cascivo-color-surface) 30%, transparent) center top / 100% 1.5rem
        no-repeat,
      linear-gradient(transparent, var(--cascivo-color-surface) 70%) center bottom / 100% 1.5rem
        no-repeat;
    background-attachment: local, local;

    &[data-scroll-top]:not([data-edges='none']) {
      box-shadow: inset 0 0.5rem 0.4rem -0.4rem
        color-mix(in srgb, var(--cascivo-color-text) 12%, transparent);
    }

    &[data-scroll-bottom]:not([data-edges='none']) {
      box-shadow: inset 0 -0.5rem 0.4rem -0.4rem
        color-mix(in srgb, var(--cascivo-color-text) 12%, transparent);
    }

    &[data-scroll-top][data-scroll-bottom]:not([data-edges='none']) {
      box-shadow:
        inset 0 0.5rem 0.4rem -0.4rem color-mix(in srgb, var(--cascivo-color-text) 12%, transparent),
        inset 0 -0.5rem 0.4rem -0.4rem
          color-mix(in srgb, var(--cascivo-color-text) 12%, transparent);
    }

    /* ScrollShadow fade (HeroUI parity): box-shadow above is the static fallback;
       the mask-image gradient progressively replaces it on the same overflow edges. */
    &[data-edges='mask'][data-scroll-top] {
      mask-image: linear-gradient(to bottom, transparent, black 1.5rem);
    }
    &[data-edges='mask'][data-scroll-bottom] {
      mask-image: linear-gradient(to top, transparent, black 1.5rem);
    }
    &[data-edges='mask'][data-scroll-top][data-scroll-bottom] {
      mask-image: linear-gradient(
        to bottom,
        transparent,
        black 1.5rem,
        black calc(100% - 1.5rem),
        transparent
      );
    }
  }

  /*
    Scroll-state container queries — the same two shadows, with no JavaScript.

    Everything above is driven by `data-scroll-*` attributes that a `scroll` listener in
    `scroll-area.tsx` toggles; the listener's entire job is to tell CSS something CSS can
    now ask the scroller itself. `container-type: scroll-state` makes `.root` answer
    `scrollable: top/bottom` directly.

    A container query cannot style its own container, but it CAN style that container's
    pseudo-elements (verified in Chromium 141: a `::before` on the scroller picks up its
    own `scroll-state` query). So the shadows move to two zero-height sticky pseudos
    pinned to the block edges. They are block boxes in a block container, so they add no
    height and shift nothing.

    Progressive enhancement (Chrome 133+). Elsewhere the attribute rules above still run,
    unchanged, because `scroll-area.tsx` keeps registering the listener there.
  */
  @supports (container-type: scroll-state) {
    .root[data-edges='shadow'] {
      container-type: scroll-state;

      &::before,
      &::after {
        content: '';
        display: block;
        position: sticky;
        z-index: 1;
        block-size: 0;
        opacity: 0;
        pointer-events: none;
        transition: opacity var(--cascivo-duration-150) var(--cascivo-ease-out);
      }

      &::before {
        inset-block-start: 0;
        box-shadow: 0 0.5rem 0.4rem -0.4rem
          color-mix(in srgb, var(--cascivo-color-text) 12%, transparent);
      }

      &::after {
        inset-block-end: 0;
        box-shadow: 0 -0.5rem 0.4rem -0.4rem
          color-mix(in srgb, var(--cascivo-color-text) 12%, transparent);
      }
    }

    @container scroll-state(scrollable: top) {
      .root[data-edges='shadow']::before {
        opacity: 1;
      }
    }

    @container scroll-state(scrollable: bottom) {
      .root[data-edges='shadow']::after {
        opacity: 1;
      }
    }
  }
}
